-- KB-025 tenant isolation across retrieval, memory and tools. Additive semantic correction.
-- Historical findings, evidence, assessments and deployment decisions are not changed.
UPDATE risk_knowledge_entries SET problem_json='{"statement":"An agent can search, summarise, export or modify another customer''s data even when the web application appears isolated.","customer_symptom":"A user or operator may observe an agent can search, summarise, export or modify another customer''s data even when the web application appears isolated; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"A user, compromised agent or mis-scoped service identity can exploit missing or inconsistent tenant binding across vector retrieval, persistent memory, caches, asynchronous jobs, tool calls and exports, exposing another tenant''s records, metadata or actions.","affected_assets":["tenant-scoped documents and vector search indexes","memory stores and cached retrieval results","background job payloads and queues","tool, API and provider service identities","exports, logs and downstream data sinks"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-tenant agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"Between the authenticated tenant and the retrieval, memory, cache, asynchronous execution, tool, export and logging layers that must preserve that tenant''s authority.","operational_impact":"If an agent can search, summarise, export or modify another customer''s data even when the web application appears isolated, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-025 tenant identity propagation, role, namespace, retrieval or vector index change","ARL-KB-025 cache partition, memory, job, tool, export or log pipeline change","ARL-KB-025 cross-tenant leak, metadata exposure, stale-claim or isolation-bypass incident","ARL-KB-025 assessed scope, build version or evidence expiry change"],"review_status":"candidate semantic correction; independent practitioner and customer validation required"}', content_digest='752f0862cf283216565c21cc7319c845a0dc1de13754c2032e502549abb84138', updated_at='2026-10-10' WHERE id='ARL-KB-025';
UPDATE risk_knowledge_checks SET objective='Determine whether authenticated tenant identity is enforced and fails closed across direct APIs, vector retrieval, memory, caches, asynchronous jobs, tools, exports and logs for the exact assessed build.', method='Review the approved tenant-isolation matrix and version-bound source/configuration, including vector namespace filters, cache partitioning, service identities and async tenant propagation. With separately authorised staging and synthetic Tenant A/B identities and data, execute bounded positive same-tenant and negative cross-tenant scenarios through each applicable path; verify responses, retrieved provenance, downstream effects and attributable audit events.', required_evidence_json='["ARL-KB-025 exact assessed system, version, environment, synthetic tenant and actor identities, retrieval collections, memory stores, cache partitions, background jobs, tools, exports and log scope","ARL-KB-025 organisation-approved tenant and operation isolation policy, permitted data-sharing matrix, identity propagation rules, exceptions and accountable owner","ARL-KB-025 source or configuration evidence for mandatory tenant-scoped retrieval filters, vector namespaces, memory/cache partitioning, job identity context, tool authorization, export/log segregation and fail-closed missing-claim paths","ARL-KB-025 bounded positive evidence of authorised synthetic Tenant A/B requests, searches, memory, cache, jobs, tool calls and exports returning only approved tenant data and state changes","ARL-KB-025 bounded negative evidence of cross-tenant IDs, vector results, memory/cache reuse, asynchronous jobs, tool execution, indirect references, exports, log access and absent-tenant-claim variants denied before data exposure or side effects","ARL-KB-025 observed runtime tenant binding, vector/retrieval filter decisions, item provenance, output, tool and downstream authorization events, before-and-after state and audit records proving allow and deny outcomes","ARL-KB-025 tester and reviewer identity, written authorisation, roles, timestamps, exact assessed version, evidence digest, unsupported paths, exceptions and accountable human decision"]', pass_condition='KB-025 passes only after accountable human review of exact-version source, policy, synthetic same-tenant success and observed cross-tenant denial before metadata or content disclosure or side effects across each applicable retrieval, memory, cache, asynchronous, tool, export and log path, with correlated audit evidence and explicit limits.', fail_condition='KB-025 fails or requires review if tenant identity is omitted or confused, another tenant''s contents or metadata are returned through any path, an unauthorised tool or export action executes, isolation fails open, or exact-version tests, runtime observations or accountable human review are missing.', content_digest='97e0d41bc2df59df8be73106289f1dbfc898b10fa5e513e10c482e82adecc2f4', updated_at='2026-10-10' WHERE entry_id='ARL-KB-025';
UPDATE risk_knowledge_solutions SET retest_acceptance_json='["ARL-KB-025: The exact remediated tenant-isolation policy, identity propagation design, affected data paths, deployed version and signed evidence digests are recorded.","ARL-KB-025: Bounded synthetic same-tenant retrieval, memory, cache, job, tool and export operations succeed with approved outputs and state changes.","ARL-KB-025: Cross-tenant and missing-claim variants are denied before foreign content, metadata or side effects across applicable retrieval, cache, memory, job, tool, export and log paths, with attributable logs.","ARL-KB-025: An accountable human reviewer records unsupported paths, residual exceptions, limitations and the exact-version retest decision."]', content_digest='15b3b5fbae26320094d9336257ca4a1b5353412c2015d7a8ee27b13958a99f14', updated_at='2026-10-10' WHERE entry_id='ARL-KB-025';
